INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('from shapely.geometry import Point','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES(' ','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('QESIS_COUNTRIES = ["BHR","SAU","ARE","QAT","CHL","ISR","MEX","BEL","USA","IND",','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('    "KOR","ESP","ZAF","FIN","POL","IDN","AUT","AUS","NOR","MYS","FRA","JPN",','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('    "BRA","NZL","CAN","CHE","NLD","SWE","DNK","GBR","ITA","DEU"]  # excludes HKG/TWN/SGP','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('SCENARIOS = ["ssp1","ssp3"]  # optimistic, pessimistic','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('YEARS = [2030, 2050, 2080]','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES(' ','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('results = []','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('for iso3 in QESIS_COUNTRIES:','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('    country = pycountry.countries.get(alpha_3=iso3)','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('    for scenario in SCENARIOS:','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('        for year in YEARS:','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('            aq = gh.get_water_stress(country=iso3, scenario=scenario, year=year)','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('            bws = aq["bws_cat"].mean() * 100  # normalise to 0-100','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('            results.append({"iso3":iso3,"scenario":scenario,"year":year,"bws":round(bws,1)})','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES(' ','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('df = pd.DataFrame(results).pivot_table(index="iso3",','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('    columns=["scenario","year"], values="bws")','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('df.to_excel("Aqueduct_4_Batch_35.xlsx")','','','','','','','','','','','');
INSERT INTO "v8_aqueduct_4_0_batch_35" VALUES('# Note: Network access required for WRI Aqueduct API. Run in DPhil computational environment.','','','','','','','','','','','');
INSERT INTO "v8_bau_assumptions" VALUES('ESE REGIONAL MULTIPLIER GROUPS (IEA STEPS + SSP3-7.0)','','','','','');
INSERT INTO "v8_bau_assumptions" VALUES('Group / Countries','f_t2030','f_t2050','f_t2080','Countries','Rationale');
INSERT INTO "v8_bau_assumptions" VALUES('A — Fossil Lock-In','1.04','1.08','1.14','BHR SAU ARE QAT ISR IND IDN ZAF POL','STEPS projects continued fossil electricity dominance; import/supply risk grows');
INSERT INTO "v8_bau_assumptions" VALUES('B — EU Strong Transition','0.9','0.78','0.64','DEU FRA GBR BEL ESP ITA NLD CHE','EU ETS + carbon border mechanism drives deep decarbonisation; ESE falls substantially');
INSERT INTO "v8_bau_assumptions" VALUES('C — Americas Mixed','0.96','0.9','0.82','USA CAN MEX BRA CHL','Partial IRA/STEPS transition; fossil dependence reduces moderately');
INSERT INTO "v8_bau_assumptions" VALUES('D — Asia-Pacific Mixed','0.97','0.92','0.85','JPN KOR AUS NZL MYS SGP HKG TWN','LNG-heavy mix with gradual renewables expansion under STEPS');
INSERT INTO "v8_bau_assumptions" VALUES('E — Nordic/Alpine Clean','0.88','0.74','0.6','FIN NOR AUT SWE DNK','Already near-zero carbon electricity; stress falls under energy transition');
INSERT INTO "v8_bau_assumptions" VALUES('CAT CURRENT POLICIES TRAJECTORY — CSovE GROWTH MULTIPLIERS','','','','','');
INSERT INTO "v8_bau_assumptions" VALUES('CAT ordinal 6: Critically Insufficient','1.08','1.16','1.24','SAU BHR QAT IDN MEX','No credible transition; emissions continue rising under current policies');
INSERT INTO "v8_bau_assumptions" VALUES('CAT ordinal 5: Highly Insufficient','1.05','1.1','1.16','ARE JPN ZAF KOR SGP USA CAN HKG TWN ISR','Weak NDCs; slow emissions growth; CSovE worsens gradually');
INSERT INTO "v8_bau_assumptions" VALUES('CAT ordinal 4: Insufficient','1.02','1.05','1.08','MYS BRA IND AUS POL NZL CHE DEU FRA GBR + 9 BIG*','Some transition effort; CSovE stable-to-modest increase');
INSERT INTO "v8_bau_assumptions" VALUES('CAT ordinal 3: 2°C Compatible','0.95','0.88','0.8','NOR SWE DNK*','Strong policies in place; CSovE trajectory improving');
INSERT INTO "v8_bau_assumptions" VALUES('CAT ordinal 2: Almost Sufficient','0.9','0.8','0.68','—','Near 1.5°C pathway; significant CSovE reduction');
INSERT INTO "v8_bau_assumptions" VALUES('CRD: IEA CRITICAL MINERALS STEPS + USGS DEPLETION (t2080)','','','','','');
INSERT INTO "v8_bau_assumptions" VALUES('Mineral Producers','0.92','0.85','0.78','AUS CAN CHL ZAF BRA NOR IDN','Increased demand = strategic resource advantage; CRD decreases');
INSERT INTO "v8_bau_assumptions" VALUES('Gulf States','1.04','1.08','1.12','BHR SAU ARE QAT','Oil-rich but mineral-poor; import dependence rises with EV transition');
INSERT INTO "v8_bau_assumptions" VALUES('Heavy-Tech Importers','1.08','1.15','1.22','JPN KOR DEU GBR FRA ITA BEL NLD CHE TWN','High-tech manufacturing; critical mineral imports = growing exposure');
INSERT INTO "v8_bau_assumptions" VALUES('Standard Importers','1.05','1.1','1.17','All others','General import dependence; IEA STEPS demand growth outpaces supply');
INSERT INTO "v8_bau_assumptions" VALUES('★ NOTE ON ESE: Electricity Stress Exposure is reported as a standalone Lindblad collapse operator (L_n in D[ρ]). It does NOT enter the QESIS_Theory formula. ESE = γ_n = CONFLICT×0.40 + FISCAL_STRESS×0.35 + GEOPOL_RISK×0.25. Time projections shown for informational / scenario analysis purposes only.','','','','','');
INSERT INTO "v8_bau_assumptions" VALUES('★ CSE LOG-DAMPENING: TeleGeography BAU growth model. Factors ×1.18/×1.28/×1.35 applied to CSE_t0. Countries with CSE_t0=0 (KOR, AUT, CHE) retain 0 — no cable baseline exists in SubmarineMap/EMODnet for these ISO codes as of 2025.','','','','','');
INSERT INTO "v8_bau_assumptions" VALUES('★ BIG GATE (Axis 7 — Epistemology): 14 countries lack full CSovE primary source coverage (<75%). CSovE values estimated from CAT ordinals, institutional profiles, and ClimateTRACE analogue proxies. All marked * to prevent false-precision ranking.','','','','','');
INSERT INTO "v8_bau_assumptions" VALUES('★ WSE PROXY CASES: SGP assigned WSE=100 (desalination-dependent; no natural freshwater). TWN uses KOR Aqueduct BAU trajectory (East Asia regional proxy). HKG uses mainland PRD river dependency model (SSP3-RCP7.0 escalating).','','','','','');
