INSERT INTO "v8_corrections_log_v7_1" VALUES('E1','Proxy column renamed, NOT overwritten','Instruction said to overwrite the proxy column; that column is the genuine FPE data on which the v7 thesis now relies (it reproduces the FPE means and correlations). Overwriting would have destroyed the FPE axis. Applied instead: header renamed to ''FPE Risk (0-100)''; real ESE added as a NEW column (col 35) and into the Physical Constraints Matrix.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E2','Date-corruption recovery','24/35 uploaded ESE values were Excel-coerced to dates; recovered as score = day + month/10 (e.g., 2026-03-19 → 19.3). Full mapping in ⚡ ESE v7 Telemetry.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E3','Coverage disclosure','ESE covers 29/35 sample countries; ARE, BHR, IDN, MYS, QAT, SAU = EPIS. Six out-of-sample countries (CHN, CZE, GRC, IRL, PRT, TUR) stored but excluded from all sample statistics.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E4','Density matrix recomputed','Canonical set {WSE, CSE, REE, FPE, ODI, ESE}, n=26: CR = 0.144 (from 0.146), Frobenius 0.614, dominant eigenmode 43.8%. ESE–WSE +0.523; ESE–ODI −0.451. 7-axis robustness CR = 0.188.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E5','fsQCA ESE tests','ESE·REE NOT quasi-necessary (0.278) — hypothesis rejected; ESE·REE near-perfectly sufficient (0.959) defining the IND/ZAF energy–mineral pathway; ~ESE present in 4 of 5 European paths; REE necessity strengthens to 0.957; 7-condition solution consistency 0.818 / coverage 0.876.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E6','Provenance flag — ACTION REQUIRED','The ESE dataset arrived without source documentation. Before submission, record derivation (sources, weights, vintage) in the Telemetry sheet, or the EPIS gap is replaced by an unverifiable column.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E7','ESE provenance documented + six gaps closed','Methodology memo received (Ember 30% carbon / IEA-Eurostat 30% cost / WB-ENTSO-E 40% grid, min-max 0-100). ARE 23.2, QAT 28.4, BHR 34.5, SAU 42.3, MYS 44.5, IDN 57.4 built from sourced components (audit trail in ⚡ ESE v7 Telemetry). Marked as estimates pending primary-portal verification; component documentation for the original 29 scores remains outstanding.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E8','Full-coverage recomputation','Density matrix n=32: CR = 0.096 (S=1.621), Frobenius 0.515, FPE-ODI +0.689 restored. fsQCA n=35: REE necessity 0.916; ESE·REE sufficiency 0.955 (from 0.959 at n=29) — holds; IDN joins the pathway. Thesis text (v7-corrected docx) still cites v7.0/7.1 matrix values — one final consistency pass required before submission.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E9','v7.3 canonical two-tier adopted','Global n=32 CR=0.096 declared canonical; n=26 dependent-core sub-matrix CR=0.144 declared as targeted sub-analysis. Master thesis cascaded (Ch I, III, IV, V, VII) and Chapter VIII integrated; fidelity finalised (0.934/0.785/0.825); fsQCA ESE robustness at n=35 (0.809/0.862; ESE·REE suf 0.955). Zero numeric discrepancy between workbook and thesis as of 2026-06-11.');
INSERT INTO "v8_corrections_log_v7_1" VALUES('E10','v8.0 — full audit closure','ESE re-derived for all 35 from unified component table (mean |Δ| 8.2 vs v7.2; superseded scores retired). Two-tier coupling updated: 0.110 global / 0.163 core; ESE·REE sufficiency 0.953 with Poland joining the pathway. Outcome anchors declared (80/55/30) + anti-circularity test passed (0.708 vs 0.807). Figures I-1, I-2, II-1 generated and embedded in the thesis. Viva prep sheet added. Zero numeric discrepancy thesis↔workbook as of 2026-06-11.');
