INSERT INTO "v8_cover" VALUES('v6.1','March 2026','Energy data','Replaced McKinsey/Statista 2023 with IEA WEO 2025 (Annex A, Nov 2025). Global 2024e: 31,229 TWh. EU STEPS 2050: 4,816 TWh. NZE 2050 global: 80,175 TWh. Added CO₂ intensity trajectory. Added tech cost assumptions (Solar/Wind/Gas).','','');
INSERT INTO "v8_cover" VALUES('v6.1','March 2026','REE data','Replaced USGS MCS 2024 with USGS MCS 2025 (January 2025). Key revisions: Russia reserves 10Mt→3.8Mt; Vietnam reserves 22Mt→3.5Mt; Australia reserves 105.7Mt→135.7Mt; Nigeria added as new producer (13,000t 2024e); World total 2024e: 390,000t; US net import reliance fell to 80%.','','');
INSERT INTO "v8_cover" VALUES('v6.1','March 2026','CRMA update','Added CRMA Regulation (EU) 2024/1252 (in force 23 May 2024) full targets: extraction ≥10%, processing ≥40%, recycling ≥25%, dependency ≤65% per SRM. Confirmed non-binding benchmark status (per EP ThinkTank, Nov 2024).','','');
INSERT INTO "v8_cover" VALUES('v6.1','March 2026','OECD TiVA 2025','Added new sheet with OECD TiVA 2025 Australia sample data (2015–2022). Domestic Value Added in Foreign Final Demand by sector. Mining B07 = USD 72.5bn (2022). Full 35-country expansion: DPhil priority.','','');
INSERT INTO "v8_cover" VALUES('v6.1','March 2026','QESIS+ REE scores','Updated REE Base/Stress for USA/CAN/AUS cluster (55.5/62.5) reflecting improved US domestic production and AUS reserve revision. EU cluster updated to 82.5/91.5 (China share 70% per MCS2025 vs 72% MCS2024).','','');
INSERT INTO "v8_cover" VALUES('v6.1','March 2026','KEY_SOVEREIGNTY','Expanded from 5 → 35 countries via Jurisdictional Tier Method. New sheet: 🔑 KEY_EFF Sovereignty (35). Tiers: A-EU (GDPR/NIS2), B-5E (Five Eyes), B-NA (NATO), C-HY (Hybrid), D-EM/BR, E-AU (Autocratic). CP_INFRA_PM = 0.50 universally identified as global sovereignty floor.','','');
INSERT INTO "v8_cover" VALUES('v6.1','March 2026','EFF_SOVEREIGNTY','Expanded from 3 → 35 countries. EFF_SOV_EXT computed for all. COLLECTED: DEU, ESP, USA, BRA, SGP. INFERRED (regulatory proxy): 30 countries. BIG Gate PASS (≥0.85): EU Tier A + B-5E. FAIL: MENA, BRA, IDN, MEX, ZAF.','','');
INSERT INTO "v8_cover" VALUES('v6.1','March 2026','Krippendorff α (fsQCA Table 2)','2-coder inter-coder reliability design. α = 0.9155 (interval metric, n=15×5=75 units). Exceeds DPhil threshold ≥0.70. Per-condition α: LEGAL_ACT=0.7114, EXEC_DISC=0.8237, PARL_RES=0.7628, INVEST=0.9253, CHOKE_AWR=0.9495.','','');
INSERT INTO "v8_cover" VALUES('v6.1','March 2026','Aqueduct 4.0 Batch (D07)','Gap D07 resolved for 32/35 countries. New sheet: 💧 Aqueduct 4.0 Batch (35). Data: WSE baseline + 2030/2050/2080 × SSP1 (optimistic) + SSP3 (pessimistic). QESIS+ Col T (WSE_2050_pes) updated for all 32. New cols: WSE_2030_pes, WSE_2080_pes. HKG/TWN/SGP remain N/A (Aqueduct city-state exclusion). pygeohydro code documented.','','');
