INSERT INTO "v8_csove_methodology" VALUES('Indicator Name','Carbon Sovereignty Exposure (CSovE)','','');
INSERT INTO "v8_csove_methodology" VALUES('Purpose','Measures the epistemic gap between what a sovereign actor officially claims about its carbon trajectory and what independently verified data shows. This is the carbon-specific operationalisation of the Epistemic Sovereignty Gap.','','');
INSERT INTO "v8_csove_methodology" VALUES('Research Question Answered','How large is the gap between what a sovereign actor claims about its carbon position and what independently verified reality shows?','','');
INSERT INTO "v8_csove_methodology" VALUES('QESIS+ Weight','CSovE_GAP weighted at 12% in QESIS_EXTENDED formula. Equivalent to CRD weight. Does not modify existing 5-dimension QESIS_Theory score.','','');
INSERT INTO "v8_csove_methodology" VALUES('Formula','QESIS_EXTENDED = QESIS_Theory × 0.88 + CSovE_GAP × 0.12','','');
INSERT INTO "v8_csove_methodology" VALUES('SECTION 2: SUB-INDICATORS','','','');
INSERT INTO "v8_csove_methodology" VALUES('CSovE_CLAIM (0–100)','NDC ambition deficit: how ambitious vs reality is the official pledge? Formula: (trajectory_gap × 0.40) + (CAT_discount × 0.60)','UNFCCC NDC Registry; Climate Watch WRI; Climate Action Tracker','CAT 2025; ClimateWatch 2025');
INSERT INTO "v8_csove_methodology" VALUES('CSovE_VERIFY (0–100)','Real substrate verification gap. Formula: (underreport_factor × 0.40) + (offset_integrity_deficit × 0.35) + (governance_deficit × 0.25)','ClimateTRACE v5.4; ICVCM Dec 2025; World Bank CPD Aug 2025','Multiple');
INSERT INTO "v8_csove_methodology" VALUES('CSovE_GAP (0–100)','FINAL SCORE — arithmetic mean of CLAIM and VERIFY. This IS the carbon-specific Epistemic Sovereignty Gap. Formula: (CLAIM + VERIFY) / 2','Computed','Derived');
INSERT INTO "v8_csove_methodology" VALUES('SECTION 3: TIER CLASSIFICATION','','','');
INSERT INTO "v8_csove_methodology" VALUES('INFR (75–100)','Maximum epistemic gap. Underreport factor >2.5 or no carbon governance. SUBSTRATE_RUPTURE risk. Fossil states: RUS, IRN, BHR, KWT, OMN, SAU, QAT, MEX, IDN, NGA.','','');
INSERT INTO "v8_csove_methodology" VALUES('EPIS (50–74)','Significant gap, partial governance. IMAGINARY_PROJECTION risk. Most A-EU developing economies: IND, JPN, KOR, BRA, ZAF, POL, ARG, PAK.','','');
INSERT INTO "v8_csove_methodology" VALUES('ACTIVE (0–49)','Active pricing mechanisms, verified trajectories. Coherent SYMBOLIC_ASSERTION. EU core + NOR + SGP + AUS + NZL: DEU, FRA, CHE, NOR, GBR, NZL, SGP, AUS, NZL, MAR.','','');
