INSERT INTO "v8_energy_2050_projections" VALUES('X-01','Global Gen × EU Share (ESE)','EU = 4,467–5,177 TWh vs 58,081 TWh global (STEPS) / 80,175 TWh (NZE) = 6.2–7.2% of world generation by 2050. EU is net consumer at global scale.','EU sovereignty is structurally constrained: high demand, low proportional generation → chronic ESE exposure regardless of contractual ESC compliance scores.','Ch.3 Methodology','Formalise ESE as function of EU/Global generation ratio; test correlation with QESIS+ ranks for EU-27 members.','Foucault (infrastructural power)','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('X-02','REE Axis × Transport 2050 (CRMA)','Transport demand: 989–1,064 TWh by 2050, driven by EV. EV magnets require NdFeB → China dependency ≥65% (all scenarios breach CRMA 2030 targets).','Circular constraint: energy sovereignty requires EV/wind build-out; build-out requires REE sovereignty; REE sovereignty remains unachieved. Self-referential physical constraint.','Ch.4 REE Axis','Lindblad operator / non-separability proof: ρ_REE and ρ_Energy cannot be disentangled — ρ_Total ≠ ρ_W ⊗ ρ_E ⊗ ρ_C ⊗ ρ_R.','Morin (polycrisis)','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('X-03','WSE Axis × Generation Scaling','Global generation +133% by 2050 requires massive thermal/cooling infrastructure. High-WSE countries (BHR=100, SAU=99.6) face compound constraint: more electricity for desalination AND water-limited generation.','Non-linear compounding effect: QESIS_PLUS linearises WSE but energy-water nexus is multiplicative. Underestimates sovereign risk for MENA, SGP-class nodes.','Ch.5 Physical Constraints Matrix','Introduce WSE² interaction term in QESIS_PLUS for energy-intensive jurisdictions. Test on BHR, SAU, ARE, SGP.','Bauman (liquidity)','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('X-04','ESC-SRF × Buildings Sector (SRF.BC.3)','Buildings sector = 2,145–2,546 TWh by 2050 (EU). Cloud/AI data centres classified under buildings energy in EU stats. AWS ESC (SRF.BC.3) mandates EU-only infrastructure powered from EU grid.','Sovereign cloud energy source is EU-grid-dependent. EU grid relies on wind/solar requiring REE supply chains under CRMA breach (X-02). ESC contractual sovereignty ≠ physical energy sovereignty.','Ch.6 ESC Compliance','Map AWS ESC power consumption trajectory against EU grid decarbonisation scenarios. Compute ''physical sovereignty gap'' per scenario.','Arendt (paralysis)','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('X-05','Scenario Uncertainty × Planning Horizon (All axes)','FF55 vs Radical Action = 710 TWh gap by 2050 ≈ France+Spain current total generation. No EU member can plan cable, water, or cooling infra with deterministic confidence.','710 TWh uncertainty band is a measurable epistemic sovereignty gap. Countries with high CSE dependency (UK, SGP) cannot route sovereign infrastructure around an unknown demand ceiling.','Ch.7 DPhil Gaps','Formalise epistemic uncertainty band as 5th dimension in QESIS_PLUS: Scenario Variance Index (SVI = σ_scenarios / μ_scenarios per country).','Bauman (liquid modernity)','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('X-06','2030 Inflection × CRMA Compliance','Global generation = ~38.7 PWh in 2030 (STEPS). EU FF55 target = 3.6 PWh (9.7% share). CRMA 2030: dependency still ≥65%, recycling ≤22%, processing permits 16 months (target 15). Zero targets met on Base-case.','EU builds its 2030 energy transition infrastructure (wind, EV, heat pumps) entirely on a CRMA-non-compliant REE supply chain. Structural sovereignty paradox: the transition mechanism is itself non-sovereign.','Ch.4 REE + Ch.6 ESC','Index ''Transition Sovereignty Score'' = f(CRMA compliance rate, REE localisation %, permit lead time). Compute for all 27 EU members.','Morin (polycrisis) + Foucault','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('SECTION D — QESIS_PLUS WEIGHT RECALIBRATION NOTE (2050 Evidence Update)','','','','','','','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('Axis','Current Weight','2050 Evidence','Recalibration Rationale','Proposed Δ Weight','New Weight (indicative)','','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('WSE — Water Stress','0.2975','Energy-water nexus intensifies: +133% global generation requires proportional cooling/hydro water. MENA compound constraint confirmed.','Non-linear energy-water coupling justifies upward revision for high-generation-intensity jurisdictions.','+0.01–0.03 (context)','0.31 (high-WSE nodes)','','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('CSE — Cable Stress','0.2975','72 PWh global generation requires massive cable infrastructure expansion; 343-cable registry already shows 40%+ aging (>20yr).','No weight change but urgency of CSE gap (25/35 countries missing) elevated by 2050 generation scaling.','0.00 (pending data)','0.2975','','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('REE — Rare Earths','0.1500','Transport 989–1,064 TWh by 2050 = EV-driven; EV = NdFeB magnets = China dependency. CRMA breach confirmed across all scenarios to 2030.','REE is no longer a niche axis — it is the binding constraint of the energy transition. Upward revision warranted.','+0.02–0.05','0.17–0.20','','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('ESE — Electricity Stress','0.1700','EU = 6.2–7.2% of global generation; structurally energy-importing. Foreign energy provider exposure is chronic, not transitional.','Energy dimension of ESE (not just cloud providers) should be explicitly modelled as sub-component.','0.00 (split proposed)','0.1700','','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('ODI/CRD — Digital','0.2550','No direct 2050 energy projection update to ODI/CRD. Indirect: data centre growth within buildings sector (2,145–2,546 TWh) raises digital infra energy intensity.','Stable. Monitor data centre share of buildings sector post-2025.','0.00','0.2550','','','','','','');
INSERT INTO "v8_energy_2050_projections" VALUES('📚 SOURCES (v6.0 — updated)  |  Global generation: IEA World Energy Outlook 2025, Annex A Free Dataset World (November 2025). EU generation by scenario: IEA WEO 2025, Annex A Free Dataset Regions (European Union). Power generation technology costs: IEA WEO 2025 Power Generation Assumptions by Scenario (xlsb, November 2025). CRMA targets: EU Critical Raw Materials Act, Regulation (EU) 2024/1252 (in force 23 May 2024). QESIS_PLUS formula: WSE×0.2975 + CSE×0.2975 + ODI×0.17 + CRD×0.085 + REE×0.15. Replaces: McKinsey Global Energy Perspective 2023 (via Statista) and Eurelectric 2023.','','','','','','','','','','','');
