INSERT INTO "v8_esc_compliance" VALUES('📐 CP_* METHODOLOGY: Five ESC compliance pillars assessed on 0–1 scale. CP_CONTRACT=contractual data sovereignty; CP_DATA_RESIDENCY=enforced data locality; CP_LE_REQUESTS=law enforcement access controls; CP_INFRA_PM=physical access governance; CP_PRIV_ACCESS=operator zero-access architecture (Nitro/Confidential Compute). CP_JURISDICTION_INDEX = weighted mean. EU GDPR threshold: ≥0.75 for compliant deployment. EFF_SOVEREIGNTY_EXT = Research_Pilot_EFF_SOVEREIGNTY_EXT (BIG Gate, 2026-02-13): mean of KEY_SOVEREIGNTY_norm, SUPPLYCHAIN_INTEGRITY_norm, RESOURCE_SOV, RESTORATION_SOV, CP_JURISDICTION_INDEX_AVG. BIG Gate PASS threshold: ≥0.85 (Observability & Eff Coverage met). Pilot jurisdictions: DEU, ESP (0.88125), USA (0.87333), BRA, SGP (0.61333). Key gap: CP_INFRA_PM consistently 0.5 — physical infrastructure management remains weakest sovereignty pillar globally.','','','','','','','','','','','','','');
INSERT INTO "v8_esc_srf_framework" VALUES('  BUSINESS CONTINUITY & CONTINGENCY PLANNING','','','','','','');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.BC.1','Operational Autonomy within EU Jurisdiction — AWS ESC operates independently within EU; critical systems function during global connectivity disruption','AWSCA-20.2','AWSCA-20.3, AWSCA-10.1, AWSCA-10.3, AWSCA-13.13','','Dedicated runbooks; EU-only staff operations; autonomous compute/storage/identity/monitoring');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.BC.2','Isolation Validation & Network Resilience — periodic testing of continued operation during connectivity disruption','AWSCA-20.3','AWSCA-10.3','','Annual exercise: complete disconnect from AWS Backbone Network');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.BC.3','Dedicated, Segregated EU Infrastructure — physically distinct from global AWS infra','AWSCA-20.2','AWSCA-13.13','','Geographic and logical boundary enforcement; redundancy for fault tolerance');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.BC.4','Contingency, Disaster Recovery & Supply Chain Readiness — geopolitical/network isolation scenarios covered','AWSCA-1.5','AWSCA-10.3, AWSCA-10.4','','Risk register updated semi-annually; capacity planning monthly');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.BC.5','EU-Resident Incident Response — dedicated IR capability staffed by EU-resident AWS ESC Staff','AWSCA-20.4','AWSCA-8.1, AWSCA-8.2','','Customer Content handled exclusively by ESC Staff; severity-rated ticket tracking');
INSERT INTO "v8_esc_srf_framework" VALUES('  DEVELOPMENT & CONFIGURATION MANAGEMENT','','','','','','');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.CM.1','Data Residency — Customer Content & Customer-Created Metadata maintained within EU boundaries','AWSCA-20.6','AWSCA-13.17','','Exceptions only: customer instruction or binding governmental order');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.CM.2','Localized Logging & Monitoring — regionalized logs; tamper-proof; remain within ESC boundaries','AWSCA-20.6','AWSCA-13.12, AWSCA-8.1','','Logs protected from unauthorized modification; retained per defined schedule');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.CM.3','Sovereign Cryptography & Certificate Management — EU root of trust; key lifecycle entirely within EU','AWSCA-20.14','AWSCA-1.2, AWSCA-4.5, AWSCA-4.12','✅ CloudHSM','Jan 2026 update: separated RoT, KMS logical security (AWSCA-4.5), KMS physical offline recovery (AWSCA-4.12). CloudHSM provides FIPS 140-2 Level 3 HSM for KMS key material — no single AWS employee access.');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.CM.4','Controlled Change — ESC Staff maintain change control over all ESC deployments','AWSCA-20.5','AWSCA-20.11, AWSCA-6.1–6.6','','Multi-stage review/test/approve; deployment validation detects unauthorized changes');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.CM.5','Software Supply Integrity — encrypted, integrity-controlled replica of source code within ESC','AWSCA-20.11','','','Cryptographically verified; controlled replication from authoritative sources; accessible in isolation scenario');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.CM.6','Service Onboarding Review — security & compliance review before any service onboarded to ESC','AWSCA-20.7','AWSCA-3.6','','Data classification standards reviewed annually; pre-launch security reviews mandatory');
INSERT INTO "v8_esc_srf_framework" VALUES('  DATA SECURITY & PRIVACY','','','','','','');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.DS.1','EU Law Data Request Handling — governmental requests reviewed for legal validity; minimum disclosure','AWSCA-20.13','','','ESC Staff challenge overbroad/inappropriate requests; customer notified where legally permitted');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.DS.2','Legal Validation of Law Enforcement Requests — data disclosed only per valid binding governmental order','AWSCA-20.13','','','Same control as SRF.DS.1; two-tier coverage (EU law + minimum necessary disclosure)');
INSERT INTO "v8_esc_srf_framework" VALUES('  GOVERNANCE & OVERSIGHT','','','','','','');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.GO.1','EU Jurisdiction & Contractual Clarity — contracts governed by EU Member State law; EU dispute resolution','AWSCA-20.8','AWSCA-20.7, AWSCA-15.17, AWSCA-13.14','','Data residency commitments and data subject obligations in writing');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.GO.2','Controlled, Auditable Transfers & Continuous Assurance — periodic internal & 3rd-party assessments','AWSCA-20.6','AWSCA-9.8, AWSCA-13.4, AWSCA-13.12','','Audit results available via AWS Artifact; logs tamper-proof');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.GO.3','Regulatory Engagement — EU-based regulator & industry body engagement; threat intelligence monitoring','AWSCA-13.15','','','Personnel participation in domain-relevant special interest groups');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.GO.4','Regulatory Emergency Coordination — coordinates with EU/Member State authorities during cyber incidents','AWSCA-20.4','AWSCA-13.5','','Incident status communicated per contractual agreement; ESC Staff handle customer data');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.GO.5','Independent Advisory Board — ≥4 EU-citizen/EU-resident members; ≥1 non-Amazon independent','AWSCA-20.1','AWSCA-1.1','','Advises managing directors on organisational & operational independence of ESC');
INSERT INTO "v8_esc_srf_framework" VALUES('  IDENTITY & ACCESS MANAGEMENT','','','','','','');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.IA.1','Privileged Access Governance — role/function/residency/location-based ABAC with dynamic adjustment','AWSCA-20.9','AWSCA-2.1, AWSCA-2.2, AWSCA-2.3','','Attribute-based; audit trail; periodic access reviews');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.IA.2','Geo-Fenced Authentication — MFA + location verification at session start and throughout session','AWSCA-20.9','AWSCA-2.6','','Two-factor over approved cryptographic channel; continuous geo-verification');
INSERT INTO "v8_esc_srf_framework" VALUES('  PERSONNEL MANAGEMENT','','','','','','');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.PM.1','Personnel Screening & Residency Validation — EU residency & work authorisation verified pre-access','AWSCA-20.10','AWSCA-9.2, AWSCA-9.3','','Temp authorisation re-validated by last day of validity; staff must notify residency changes');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.PM.2','Residency-Linked Logical Access — automated revocation if eligibility criteria no longer met','AWSCA-20.10','AWSCA-2.3','','Automated compliance; periodic access review');
INSERT INTO "v8_esc_srf_framework" VALUES('  PHYSICAL SECURITY','','','','','','');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.PS.1','EU-Located Infrastructure & Residency-Controlled Access — ESC infra within EU; Key Data Center Areas restricted','AWSCA-20.12','AWSCA-5.1, AWSCA-5.5','','Approved Vendor Personnel must meet EU residency/citizenship; electronic access control');
INSERT INTO "v8_esc_srf_framework" VALUES('','SRF.PS.2','Physical Security Controls & Access Monitoring — multilayered; CCTV 90-day retention; intrusion detection','AWSCA-20.12','AWSCA-5.1–5.6','✅ CloudHSM','CloudHSM appliances in physically secured Key Data Center Areas. Access revoked within 24h; quarterly access review; CCTV; electronic intrusion detection');
INSERT INTO "v8_esc_srf_framework" VALUES('📖 KEY DEFINITIONS  |  ESC Staff: EU-registered entity employees; EU residents/citizens; located in EU when performing role.  |  Customer-Created Metadata: tags, resource IDs, system configs, IAM policies.  |  Key Data Center Areas: secured rooms containing hardware processing Customer Content / Customer-Created Metadata.  |  CloudHSM: FIPS 140-2 Level 3 Hardware Security Module; provides tamper-resistant key storage underlying KMS for ESC.  |  Source: AWS ESC-SRF v2026-01-13; AWS CloudHSM User Guide.','','','','','','');
