INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Hamiltonian H_SAM(t)','H_SAM(t) = Σᵢ εᵢ(t)|i⟩⟨i|','QESIS+ EFF_SOV_EXT per country (35-country dataset)','EFF_SOV_EXT col in Sovereign_Infra_Intelligence_v6.1.xlsx','Eigenvalues εᵢ = EFF_SOV_EXT score × time index t. Makes H empirically grounded.','✅ READY — data available');
INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Initial density matrix ρ(0)','ρᵢᵢ(0) = QESIS+ᵢ / Σⱼ QESIS+ⱼ; Tr(ρ)=1','QESIS+ Base scores (35 countries)','QESIS+ Base col in 🧮 QESIS+ Country Scores','Diagonal: country''s relative sovereignty weight. Off-diagonal: fsQCA Table 2 coverage scores (pending Table 2 completion).','⚠️ PARTIAL — diagonal ready; off-diagonal needs Table 2');
INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Collapse operator Lₙ (water)','Lₙ = √(γₙ)|stressₙ⟩⟨normalₙ|','Aqueduct 4.0 WSE_2050_pes / 100','γ_WATER col in macro_template','γ_water = WSE_2050_pes/100. ISR=0.99, BHR=1.00, SAU=0.99 are highest. CHE=0.12, NZL=0.02 lowest.','✅ READY — populated in macro_template');
INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Collapse operator Lₙ (geopolitical)','Lₙ = √(γₙ)|conflictₙ⟩⟨stableₙ|','ACLED Conflict Index 2024 + WEF GRR 2026','CONFLICT_INTENSITY + GEOPOL_RISK cols','γ_geo = 0.55×CONFLICT + 0.45×GEOPOL_RISK. Ranges ISR=0.93 (max) to CHE/NOR=0.17 (min).','✅ READY — populated in macro_template');
INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Collapse operator Lₙ (fiscal)','Lₙ = √(γₙ)|stressₙ⟩⟨stableₙ|','IMF WEO Oct 2025 Debt/GDP','FISCAL_STRESS col [Debt/GDP normalized to JPN max=252%]','JPN highest γ_fiscal=1.00 (debt=252%). CHE, ARE lowest (debt<31%). Normalization: country_debt/252.','✅ READY — populated in macro_template');
INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Composite γₙ (dissipator rate)','γₙ = CONFLICT×0.40 + FISCAL_STRESS×0.35 + GEOPOL_RISK×0.25','All three sources above','LINDBLAD_γ col in macro_template','Weights: conflict > fiscal > geopolitical. Theoretically: physical disruption > economic stress > structural risk.','✅ READY — computed in macro_template');
INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Dissipator D[ρ]','D[ρ] = Σₙ(LₙρLₙ† - ½{Lₙ†Lₙ,ρ})','Composite from all collapse operators','Computed dynamically from γₙ values','PRIMARY GAP: Full matrix computation requires Python script (Lindblad_solver.py — to be built in DPhil Phase 2)','❌ GAP D06 — DPhil Phase 2');
INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Temporal evolution ρ(t)','iℏ∂ρ/∂t = [H,ρ] + D[ρ]','H_SAM + D[ρ] combined','Requires Lindblad ODE solver (QuTiP or custom)','Solve numerically over t=2024→2050 using GDP growth trajectory as time index. Output: decoherence map.','❌ GAP D06 — DPhil Phase 2');
INSERT INTO "v8_lindblad_d_rho_spec" VALUES('Interpretation','Countries with γₙ > 0.50 are ''decohering'' — sovereignty dissipating faster than governance can compensate','All data streams','MACRO_STATE calibration tier','Master''s thesis: document γₙ distribution and calibration. DPhil: solve ρ(t) trajectory and validate against 2030/2050 QESIS projections.','Master''s: ✅  DPhil: ❌ Phase 2');
