INSERT INTO "v8_oecd_tiva_2025" VALUES('QESIS+ INTEGRATION IMPLICATIONS — Australia Case Study','','','','','','','','','');
INSERT INTO "v8_oecd_tiva_2025" VALUES('REE Axis (physical)','Mining of metal ores (B07) = USD 72.5bn DVAFD 2022 → 64% of total industrial DVAFD. Australia is the world''s REE reserve archetype: sovereign in extraction (low REE exposure score), but dependent on processing (Lynas/Malaysia). TiVA confirms export-driven REE value chain.','','','','','','','','');
INSERT INTO "v8_oecd_tiva_2025" VALUES('ESE Axis (energy)','Mining/extraction energy products DVAFD: USD 119.4bn (2022). Australia = net energy exporter (ESE~low). Confirms QESIS+ low ESE assignment. WEO2025 country-level disaggregation limited; AUS not in regional free dataset.','','','','','','','','');
INSERT INTO "v8_oecd_tiva_2025" VALUES('CSE Axis (cable)','Transportation & storage DVAFD: USD 22.6bn (2022). High water transport DVAFD consistent with cable-intensive sovereign node (AUS: CSE_SCM=18.0 in QESIS+).','','','','','','','','');
INSERT INTO "v8_oecd_tiva_2025" VALUES('ICT Sovereignty','ICT DVAFD (J) = USD 9.6bn (2022) vs Total 384.5bn = 2.5%. Low ICT export intensity confirms AUS is net ICT importer → moderate CRD/ODI exposure in QESIS+.','','','','','','','','');
INSERT INTO "v8_oecd_tiva_2025" VALUES('DPhil Extension','TiVA 2025 enables panel regression: DVAFD sectors 2015-2022 × QESIS+ axes. Priority: expand to all 35 QESIS countries via OECD API. Mining B07 as REE proxy; J as digital proxy; H as cable/transport proxy.','','','','','','','','');
INSERT INTO "v8_oecd_tiva_2025" VALUES('📚 SOURCE: OECD Trade in Value Added (TiVA) 2025 Edition: Principal Indicators, Levels. OECD Data Explorer. Measure: Domestic Value Added in Foreign Final Demand. Reference area: Australia. Counterpart area: World. Annual, 2015–2022. USD Millions. Accessed March 2026. Full data: https://stats.oecd.org/Index.aspx?DataSetCode=TIVA_2023_C1','','','','','','','','','');
INSERT INTO "v8_outcome_calibration" VALUES('Independence diagnostic:','r(Y_published, composite-derived Y) = +0.487 — the published outcome incorporates strategic-autonomy assessment beyond the stress composite; it is NOT a transform of the conditions.');
INSERT INTO "v8_outcome_calibration" VALUES('Anti-circularity robustness run:','Substituting the purely composite-derived outcome (anchors above): REE necessity 0.779; four-path solution consistency 0.708 / coverage 0.651 — structure preserved at reduced strength. A circular design would inflate, not deflate, these statistics.');
INSERT INTO "v8_outcome_calibration" VALUES('Conclusion:','The published solution (consistency 0.807 / coverage 0.862) is not an artifact of outcome–condition coupling. Anchors and test mirrored in thesis §III.');
