INSERT INTO "v8_rare_earths_ree" VALUES('China','CHN','255000','270000','44000000','69.2%','Dominant supplier — high leverage over all importers. Export controls on REE technology enacted Dec 2023; extended 2024.','2024e quota: 270,000t mining. Undocumented production adds ~15-20%. Export bans on REE separation tech 2023-24.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('United States','USA','41600','45000','1900000','11.5%','Domestic producer (Mountain Pass CA + Utah/SE compounds) — net import reliance fell to 80% in 2024e (from >95%)','US MCS2025: domestic prod 2024e: 45,000t concentrates + 7,600t compounds. Net import reliance 80% in 2024e (improved).','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Burma (Myanmar)','MMR','43000','31000','','7.9%','Significant producer but opaque supply chains; exports feed Chinese processing. Production declining 2024.','Ion-adsorption clay deposits. Rapid growth 2022-23 now reversing. No official reserves data.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Australia','AUS','16000','13000','135700000','3.3%','Major reserve holder (JORC-compliant 3.3Mt); production declining 2023-24. Processing via Lynas Malaysia LAMP.','MCS2025: Reserves revised UP from 105.7Mt to 135.7Mt. Production declining: 18k(2022)→16k(2023)→13k(2024e). Lynas LAMP Malaysia.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Nigeria','NGA','7200','13000','','3.3%','Emerging producer (NEW in MCS2025) — rapid growth 2023-24; supply chain transparency unknown','NEW in MCS2025 vs MCS2024. Rapid growth to 13,000t (2024e). No reserves data available.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Thailand','THA','3600','13000','4500','3.3%','Processing hub for Myanmar output — limited domestic reserves. Production volatile.','MCS2025: Production 3,600t(2023) → 13,000t(2024e) — large jump likely reflects processing reclassification.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Russia','RUS','2500','2500','3800000','0.6%','Moderate domestic capacity — sanctions impact export routes post-2022','MCS2025: Reserves REVISED DOWN from 10,000,000t to 3,800,000t (major revision). Sanctions constrain export.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('India','IND','2900','2900','6900000','0.7%','Small but growing domestic production — monazite deposits; government push for processing','Stable production. Reserves unchanged 6.9Mt. Government IREL processing push ongoing.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Vietnam','VNM','300','300','3500000','<0.1%','Large reserves severely revised down; production declining — high import reliance for refined REE','MCS2025: Reserves REVISED DOWN from 22,000,000t to 3,500,000t (major revision). Production: 1,200t(2022)→300t(2023-24e).','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Brazil','BRA','140','20','21000000','<0.1%','Negligible production vs 3rd largest reserves globally — high import reliance for refined REE','MCS2025: Production collapsed: 80t(2022)→140t(2023)→20t(2024e). 21Mt reserves undeveloped.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Malaysia','MYS','310','130','','<0.1%','Processing hub (Lynas LAMP) — import-dependent on Australian concentrates. Own mining minimal.','MCS2025: 310t(2023)→130t(2024e) own mining. Lynas LAMP imports AUS concentrate.','','','','','','');
INSERT INTO "v8_rare_earths_ree" VALUES('Madagascar','MDG','2100','2000','','0.5%','Minor producer — not a primary QESIS country','MCS2025: Production 2,100t(2023)→2,000t(2024e). No reserves.','','','','','','');
