INSERT INTO "v8_v7_2_full_coverage_results" VALUES('D. Interpretive note','','','','','','');
INSERT INTO "v8_v7_2_full_coverage_results" VALUES('• The Gulf bloc enters as high-substrate-stress but energy-comfortable (ESE 23–42): cheap, reliable, carbon-heavy power. Its inclusion WEAKENS the global coupling (CR 0.144 → 0.096): substrate entanglement is strongest in the European core and dilutes globally — the coupling is a property of the dependent periphery-core configuration, not of the substrate as such.','','','','','','');
INSERT INTO "v8_v7_2_full_coverage_results" VALUES('• Indonesia (ESE 57.4, m = 0.68) joins India and South Africa in the energy–mineral pathway: the ESE·REE conjunction is now a three-case, cross-continental finding.','','','','','','');
INSERT INTO "v8_v7_2_full_coverage_results" VALUES('• Decide the canonical matrix sample before submission: n = 32 full coverage (CR = 0.096) is the defensible default per the original instruction; n = 26 (CR = 0.144) remains as the pre-gap-closure value. The thesis text currently cites the v7.0/7.1 numbers and needs one final pass either way.','','','','','','');
INSERT INTO "v8_v8_0_canonical_declaration" VALUES('TIER 2 — DEPENDENT CORE: n = 26 (ex ARE, BHR, IDN, MYS, QAT, SAU). CR = 0.163 (S = 1.499); dominant mode 46.4%; FPE–ODI = +0.678; ESE–WSE = +0.576; ESE–ODI = −0.521; ESE–FPE = −0.445; WSE–FPE = −0.490.','','','','','','');
INSERT INTO "v8_v8_0_canonical_declaration" VALUES('fsQCA (n = 35): REE quasi-necessary 0.916; solution 0.807/0.862; 7-condition robustness 0.809/0.860. ESE·REE: necessity 0.481 (rejected), sufficiency 0.953 — members ZAF 0.92, IND 0.80, POL 0.72, IDN 0.68. Outcome anchors 80/55/30 declared; anti-circularity test passed (see 🎯 sheet).','','','','','','');
INSERT INTO "v8_v8_0_canonical_declaration" VALUES('Fidelity (ESE anchor P10 = 22.7): DEU 0.943 (L 0.057), ESP 0.782 (0.218), GBR 0.833 (0.167). Per-axis: DEU REE 0.708; ESP WSE 0.764; GBR CSE 0.462.','','','','','','');
INSERT INTO "v8_v8_0_canonical_declaration" VALUES('All values mirrored verbatim in the master thesis v8.0 (Ch I, III, IV, V, VII, VIII). ESE fully component-derived (🔌 audit sheet). Figures I-1, I-2, II-1 embedded in the document.','','','','','','');
